import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.C_fNVUec.js";const k=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/concepts.md","filePath":"docs/concepts.md","lastUpdated":1793898059000}'),d={name:"docs/concepts.md"};function o(n,e,r,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>This page defines the objects ORC stores and how they relate, one short section each.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A project groups tasks, memories, jobs, knowledge bases, skills and scratchpads. It usually maps to one repository.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>Readable, unique name used by the CLI, MCP and URLs</td></tr><tr><td><code>scope</code></td><td>Folder on the execution host where the project&#39;s work runs</td></tr><tr><td><code>git_remote_url</code></td><td>Optional HTTPS or SSH remote; metadata only, nothing is cloned</td></tr><tr><td><code>status</code></td><td><code>active</code>, <code>paused</code> or <code>archived</code></td></tr><tr><td><code>max_workers</code></td><td>Optional per-project cap on concurrent task workers</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Main application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # later commands default to my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> infra</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # override for one command</span></span></code></pre></div><p>Resolution order: <code>-p &lt;name&gt;</code>, then <code>activeProject</code> from config. MCP tools take <code>project: &quot;&lt;name&gt;&quot;</code>, or inherit it from the <code>/mcp?project=</code> connection URL.</p><h2 id="tasks-and-status-flow" tabindex="-1">Tasks and status flow <a class="header-anchor" href="#tasks-and-status-flow" aria-label="Permalink to &quot;Tasks and status flow&quot;">​</a></h2><p>A task is one unit of work: title, body, priority (<code>low</code>, <code>normal</code>, <code>high</code>, <code>critical</code>), optional skill, agent backend and model, flow, Git branch/worktree, and GitHub issue/PR links. Tasks link to each other as dependencies.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>todo → queued → doing → review → done</span></span>
<span class="line"><span>                  │         │</span></span>
<span class="line"><span>                  ▼         ▼</span></span>
<span class="line"><span>               blocked   changes_requested → doing</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>                paused                 (any) → cancelled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>todo</code></td><td>Not started</td></tr><tr><td><code>queued</code></td><td>Claimed and waiting for a worker slot</td></tr><tr><td><code>doing</code></td><td>A session is running on it</td></tr><tr><td><code>review</code></td><td>Agent submitted work; waits for approval</td></tr><tr><td><code>changes_requested</code></td><td>Sent back with feedback</td></tr><tr><td><code>blocked</code></td><td>Waiting on a dependency or an external fix</td></tr><tr><td><code>paused</code></td><td>Stopped, for example after <code>max_review_rounds</code></td></tr><tr><td><code>done</code> / <code>cancelled</code></td><td>Terminal</td></tr></tbody></table><p><code>required_review: true</code> (the default) keeps a task in <code>review</code> until you approve. Dependents unblock when their dependencies finish.</p><h2 id="task-flows" tabindex="-1">Task flows <a class="header-anchor" href="#task-flows" aria-label="Permalink to &quot;Task flows&quot;">​</a></h2><p>Every task runs a flow graph. <code>orc-default</code> is plan → build → verify → review with bounded rework; <code>orc-human-review</code> adds your sign-off; <code>orc-review-only</code> reviews existing work. Flows are nodes (<code>agent</code>, <code>gate</code>, <code>human</code>, <code>terminal</code>) joined by declarative edges, with visit limits, budgets and a wall clock so loops always end.</p><p>See <a href="./task-flows">Task flows</a>.</p><h2 id="agent-backends" tabindex="-1">Agent backends <a class="header-anchor" href="#agent-backends" aria-label="Permalink to &quot;Agent backends&quot;">​</a></h2><p>A backend is the coding agent that runs a task node, job or chat session.</p><table tabindex="0"><thead><tr><th>Backend</th><th>Runs</th></tr></thead><tbody><tr><td><code>claude</code></td><td>Claude Agent SDK in-process (default)</td></tr><tr><td><code>claude-cli</code></td><td>The <code>claude</code> binary</td></tr><tr><td><code>codex-cli</code></td><td>The <code>codex</code> binary</td></tr><tr><td><code>acpx</code></td><td>ACP CLI, which drives 14+ agents (Gemini, Copilot, Cursor, Kiro, ...)</td></tr><tr><td><code>agentapi</code></td><td>A coder/agentapi server wrapping any local agent</td></tr><tr><td><code>a2a</code></td><td>A remote A2A endpoint</td></tr><tr><td>any other name</td><td>Passed to acpx as the agent name</td></tr></tbody></table><p><code>orc doctor</code> reports which backends are usable on the machine. <code>GET /api/backends</code> returns the same data.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p>A session is one coding-agent conversation. ORC tracks two kinds:</p><ul><li><strong>Managed sessions</strong> that ORC started: task workers, job runs, chat and terminal agents. They record backend, model, execution host, cwd, transcript, tokens and linked task.</li><li><strong>Live sessions</strong> that you started yourself in Claude Code, Codex, Cursor or Gemini. ORC discovers them from native history and lifecycle hooks and shows them as working, waiting or ended.</li></ul><p>The Sessions view lists both, with search, transcripts, <strong>Resume → Terminal</strong> and resume commands. Sessions can also be archived to ORC and handed off to another machine.</p><p>See <a href="./live-sessions">Live sessions</a> and <a href="./session-handoff">Session handoff</a>.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>A memory is a short project fact: a port, a convention, a gotcha, a decision. Each has a unique lowercase-hyphenated <code>name</code>, a <code>description</code> of when it matters, <code>content</code> (up to 800 characters by default) and a <code>priority</code> from 0 to 100. <code>context</code> loads the top memories into every session. Every edit is versioned and revertible.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ulid-ids</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Check before adding an ID field&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;All IDs are ULIDs&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --priority</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ulid-ids</span></span></code></pre></div><p>Memories import from and export to Claude Code and Codex native memory folders with <code>orc mem import|export</code>.</p><h2 id="knowledge-bases" tabindex="-1">Knowledge bases <a class="header-anchor" href="#knowledge-bases" aria-label="Permalink to &quot;Knowledge bases&quot;">​</a></h2><p>A knowledge base holds reference documents for agents to search and cite. It belongs to a project or is global. Documents come from uploads (PDF, Office, HTML, CSV, Markdown, text), Markdown written in the dashboard, or registered folders that are copied in and rescanned.</p><p>Search combines title matches, SQLite full-text search and, when embeddings are configured, vectors. Results cite passages as <code>kb:&lt;doc&gt;@&lt;rev&gt;#&lt;n&gt;</code>. Each knowledge base sets which call sources may edit it (<code>ui</code>, <code>cli</code>, <code>api</code>, <code>mcp</code>). A digest is a scheduled agent that maintains a knowledge base from comments, memories and session summaries.</p><h2 id="scratchpads" tabindex="-1">Scratchpads <a class="header-anchor" href="#scratchpads" aria-label="Permalink to &quot;Scratchpads&quot;">​</a></h2><p>A scratchpad is a working file you and agents revise together. Every save is a new revision with its author.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Content</th></tr></thead><tbody><tr><td><code>doc</code></td><td>Markdown; mermaid blocks render as diagrams</td></tr><tr><td><code>diagram</code></td><td>Excalidraw JSON</td></tr><tr><td><code>html</code></td><td>One standalone HTML page</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pad</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Auth plan&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pad</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pad</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">revisio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Agents use <code>pad_create</code>, <code>pad_get</code>, <code>pad_list</code> and <code>pad_update</code> with <code>if_revision</code> to avoid overwriting your edits.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p>A job separates what runs from when it runs.</p><table tabindex="0"><thead><tr><th>Action</th><th>Does</th></tr></thead><tbody><tr><td>Run command</td><td>Runs a shell command</td></tr><tr><td>Run agent</td><td>Runs an agent with saved instructions, backend and model</td></tr><tr><td>Create task</td><td>Creates a task, optionally starting its flow</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Trigger</th><th>Fires</th></tr></thead><tbody><tr><td><code>manual</code></td><td>On <code>orc job run</code> or the dashboard</td></tr><tr><td><code>cron</code></td><td>On a cron schedule</td></tr><tr><td><code>watch</code></td><td>On file changes</td></tr><tr><td><code>webhook</code></td><td>On a signed HTTP delivery</td></tr><tr><td><code>one-shot</code></td><td>Once</td></tr></tbody></table><p>New jobs are disabled until you enable them. Every run keeps status, logs and links to its session or task.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>A webhook source is a reusable signed endpoint that triggers jobs. Generic sources verify <code>X-Orc-Signature-256</code>; GitHub sources verify <code>X-Hub-Signature-256</code>. One source can drive several jobs, each with its own event and action filters. Delivery history keeps metadata and a payload hash, not the body. The receiver sits outside bearer auth; the per-source HMAC secret is its authentication.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p>Channels connect ORC to Telegram and Slack. In <strong>Settings → Channels</strong> you add a connection, pair approved recipients, and define ordered inbound rules that route messages to agents. Agent replies return to the same conversation. Agents send on their own with <code>channel_send</code> or <code>POST /api/channels/messages</code>. Attention notifications are a separate opt-in.</p><p>The older config-based gateway (<code>gateway.telegram</code>, <code>gateway.slack</code>) still supports <code>/status</code>, <code>/tasks</code>, <code>/approve</code>, <code>/reject</code>, <code>/jobs</code>, <code>/run</code>, <code>/mem</code> and <code>/agent</code>.</p><h2 id="human-requests" tabindex="-1">Human requests <a class="header-anchor" href="#human-requests" aria-label="Permalink to &quot;Human requests&quot;">​</a></h2><p>A human request is a question, approval or command an agent needs you to answer. It appears in <strong>Activity → Attention needed</strong>, can notify you through channels and push, and returns your answer to the waiting agent call. Managed agents create them automatically for structured questions and tool approvals; agents can also call <code>human_request</code>. Each request shows its execution host.</p><p>See <a href="./human-requests">Human requests</a> and <a href="./command-requests">Command requests</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Rules evaluate coding-agent events before selected tools run and return a deterministic decision (deny, or abstain and let the call proceed), add guidance, rewrite a command through a processor, or enqueue a job after a matching event. Policies are opt-in, scoped to a workspace folder, and versioned. Enable with <code>rules.enabled: true</code> or <code>ORC_RULES_ENABLED=true</code>.</p><p>See <a href="./agent-rules">Agent rules</a>.</p><h2 id="skills-and-agent-profiles" tabindex="-1">Skills and agent profiles <a class="header-anchor" href="#skills-and-agent-profiles" aria-label="Permalink to &quot;Skills and agent profiles&quot;">​</a></h2><p>A skill is a <code>SKILL.md</code> folder of instructions, scripts and references that agents load with <code>skill_read</code>. An agent profile (<code>.agent.md</code>) defines a specialist that any backend can run. Packages bundle skills, profiles and instructions. See <a href="./skills">Skills</a> and <a href="./agent-packages">Agent packages</a>.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>ORC keeps a central audit log of knowledge changes: memory, skill, knowledge base and digest writes, each with action, actor, source and session. Read it with <code>audit_list</code> over MCP or <code>GET /api/audit</code>. Memories and skills also keep their own change history with revert.</p>`,56)])])}const u=a(d,[["render",o]]);export{k as __pageData,u as default};
